            s = -d * 10
            if [nx, ny] == op:
                s -= 50
            if [nx, ny] in (o.get("self_path") or []):
                s -= 1
            if s > best_score:
                best_score, best = s, (dx, dy)
    else:
        center = [w // 2, h // 2]
